        "caught hold of the horns of the altar",
        "comm",
        "Note",
        "Note",
        """<strong>The altar of refuge.</strong> Adonijah seizes the altar’s horns — the four projections at its corners — claiming sanctuary. The altar was the primary asylum site in Israelite practice (Exod 21:14, 1 Kgs 2:28), comparable to ANE temple-asylum institutions across Mesopotamia and Egypt. The asylum was conditional: Exod 21:14 explicitly excluded premeditated murderers. Solomon’s response in 1:52 — "if he shows himself a worthy man, not a hair of his shall fall to the earth; but if wickedness be found in him, he shall die" — frames the rest of chapter 2: every figure who took the wrong side will be tested, and the altar will not save them.""",
        "User original",
